static void
parse_if_modified_since(struct lwan_request_parser_helper *helper)
{
    time_t parsed;

    if (UNLIKELY(!helper->if_modified_since.raw.len))
        return;

    if (UNLIKELY(lwan_parse_rfc_time(helper->if_modified_since.raw.value, &parsed) < 0))
        return;

